package com.avrix.mixin;

import com.avrix.core.KnotClassLoader;
import org.junit.jupiter.api.Test;
import org.spongepowered.asm.mixin.Mixins;
import org.spongepowered.asm.mixin.transformer.Config;
import test.mixin.game.RegistrationOnlyMixin;

import java.io.InputStream;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Objects;
import java.util.Set;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Verifies metadata of Mixin configurations generated by the loader.
 */
class GeneratedMixinConfigTest {

    /**
     * Verifies that generated configurations declare the minimum supported Mixin subsystem version.
     *
     * @throws Exception if the test class loader cannot be closed
     */
    @Test
    void shouldDeclareMinimumMixinVersion() throws Exception {
        assertThat(generatedConfigJson()).contains("\"minVersion\":\"0.8.7\"");
    }


    private static String generatedConfigJson() throws Exception {
        try (KnotClassLoader loader = new KnotClassLoader(
                new URL[0], GeneratedMixinConfigTest.class.getClassLoader())) {
            MixinTransformer transformer = new MixinTransformer(loader);
            Set<Config> configsBefore = Set.copyOf(Mixins.getConfigs());
            transformer.addMixin(RegistrationOnlyMixin.class.getName());

            Config config = Mixins.getConfigs().stream()
                    .filter(candidate -> !configsBefore.contains(candidate))
                    .findFirst()
                    .orElseThrow(() -> new AssertionError("No mixin configuration was registered"));

            try (InputStream stream = Objects.requireNonNull(
                    new MixinHostService().getResourceAsStream(config.getName()),
                    "Generated mixin config not found: " + config.getName()
            )) {
                return new String(stream.readAllBytes(), StandardCharsets.UTF_8);
            }
        }
    }
}
